import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { SITE_TEMPLATES } from "../../data/site-templates"
import { supabase } from "../../lib/supabase"
import UserPermissions, { UserActivity } from "./UserPermissions"
import * as p from "./Permissions.module.css"
import * as s from "./UsersAdmin.module.css"

/**
 * Everybody with an account, and what each of them has — FCS-090.
 * ============================================================================
 * A table of people, then one person. The table answers "who is here and are
 * they still coming back" (type, joined, last login); the detail answers "what
 * have they actually done with it" (their website and template, invoices, QR
 * codes, tracked codes, leads).
 *
 * ── TYPE IS A PLAN PLUS TWO ROLES ──────────────────────────────────────────
 * Free / Premium / Lead Generation is what they pay for. Affiliate and Admin
 * are separate things a person can ALSO be (none implies another), so they are
 * badges beside the plan rather than values of one column. Filtering by
 * "Affiliate" finds every affiliate whatever they pay.
 *
 * ── THE LIST IS CLIENT-FILTERED ────────────────────────────────────────────
 * The function returns everybody once and the search, filter and sort happen
 * here. That is fine for the hundreds this will hold, and it makes typing in
 * the search box instant instead of a server round trip per keystroke.
 *
 * ── LEADS ARE A COUNT ──────────────────────────────────────────────────────
 * The detail shows how many leads somebody has and when the latest arrived,
 * never what they say. They are strangers' contact details and an
 * administrator does not need to read them to know the form works.
 */

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("admin-users"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

const when = value => {
  if (!value) return ""
  const d = new Date(value)
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleString()
}
const day = value => {
  if (!value) return ""
  const d = new Date(value)
  return Number.isNaN(d.getTime()) ? "" : d.toLocaleDateString()
}

/** A design's name; the raw id when it is not one we know, never "Classic". */
const templateLabel = id => {
  if (!id) return "None chosen"
  const found = SITE_TEMPLATES.find(t => t.id === id)
  return found ? found.label : id
}

const FILTERS = [
  { id: "all", label: "Everyone" },
  { id: "free", label: "Free" },
  { id: "premium", label: "Premium" },
  { id: "leads", label: "Lead Generation" },
  { id: "affiliate", label: "Affiliates" },
  { id: "admin", label: "Admins" },
]

const SORTS = [
  { id: "login", label: "Last login" },
  { id: "joined", label: "Joined" },
  { id: "email", label: "Email" },
]

const Badges = ({ user }) => (
  <span className={s.badges}>
    <span className={s.badge} data-plan={user.plan}>
      {user.planName}
    </span>
    {user.isAffiliate ? <span className={s.badge} data-role="affiliate">Affiliate</span> : null}
    {user.isAdmin ? <span className={s.badge} data-role="admin">Admin</span> : null}
  </span>
)

const Tile = ({ label, value, note }) => (
  <div className={s.tile}>
    <span className={s.tileLabel}>{label}</span>
    <span className={s.tileValue}>{value}</span>
    {note ? <span className={s.tileNote}>{note}</span> : null}
  </div>
)

const Detail = ({ id, onBack }) => {
  const [info, setInfo] = React.useState(null)
  const [error, setError] = React.useState("")
  const [tab, setTab] = React.useState("overview")
  // Bumped after a real change on the Permissions tab, so the facts are re-read.
  const [tick, setTick] = React.useState(0)

  React.useEffect(() => {
    setInfo(null)
    setError("")
    setTab("overview")
  }, [id])

  React.useEffect(() => {
    let alive = true
    call({ action: "detail", id }).then(res => {
      if (!alive) return
      if (!res.ok) return setError(res.body.message || "Could not load that account.")
      setInfo(res.body)
    })
    return () => {
      alive = false
    }
  }, [id, tick])

  return (
    <div>
      <button type="button" className={s.back} onClick={onBack}>
        ‹ All users
      </button>

      {error ? <p className={s.error}>{error}</p> : null}
      {!info && !error ? <p className={s.note}>Loading the account…</p> : null}

      {info ? (
        <>
          <div className={s.detailHead}>
            <div>
              <h2 className={s.title}>{info.user.name || info.user.email}</h2>
              {info.user.name ? <p className={s.sub}>{info.user.email}</p> : null}
            </div>
            <Badges user={info.user} />
          </div>

          <dl className={s.facts}>
            <div>
              <dt>Joined</dt>
              <dd>{when(info.user.createdAt)}</dd>
            </div>
            <div>
              <dt>Last login</dt>
              <dd>{info.user.lastLogin ? when(info.user.lastLogin) : "Never signed in"}</dd>
            </div>
            <div>
              <dt>Subscription</dt>
              <dd>{info.user.subscription || "None"}</dd>
            </div>
            <div>
              <dt>Email confirmed</dt>
              <dd>{info.user.confirmed ? "Yes" : "No"}</dd>
            </div>
            {info.user.isAffiliate ? (
              <div>
                <dt>Affiliate status</dt>
                <dd>{info.user.affiliateStatus || "—"}</dd>
              </div>
            ) : null}
          </dl>

          <div className={p.tabs} role="tablist" aria-label="Account sections">
            {[
              ["overview", "Overview"],
              ["permissions", "Permissions"],
              ["activity", "Activity"],
            ].map(([key, label]) => (
              <button
                key={key}
                type="button"
                role="tab"
                aria-selected={tab === key}
                className={p.tab}
                onClick={() => setTab(key)}
              >
                {label}
              </button>
            ))}
          </div>

          {tab === "permissions" ? (
            <UserPermissions info={info} reload={() => setTick(t => t + 1)} />
          ) : null}
          {tab === "activity" ? <UserActivity id={id} /> : null}

          {tab === "overview" ? (
            <>
          <h3 className={s.h3}>Website</h3>
          {info.site ? (
            <div className={s.card}>
              <dl className={s.facts}>
                <div>
                  <dt>Business</dt>
                  <dd>{info.site.businessName || "—"}</dd>
                </div>
                <div>
                  <dt>Address</dt>
                  <dd>
                    <a href={info.site.url} target="_blank" rel="noreferrer">
                      {info.site.url.replace(/^https:\/\//, "")}
                    </a>
                  </dd>
                </div>
                <div>
                  <dt>Status</dt>
                  <dd>{info.site.status}</dd>
                </div>
                <div>
                  <dt>Template</dt>
                  <dd>
                    {templateLabel(info.site.templateId)}
                  </dd>
                </div>
                <div>
                  <dt>Last edited</dt>
                  <dd>{when(info.site.updatedAt)}</dd>
                </div>
                {info.site.sites > 1 ? (
                  <div>
                    <dt>Websites</dt>
                    <dd>{info.site.sites} (the newest is shown)</dd>
                  </div>
                ) : null}
              </dl>
            </div>
          ) : (
            <p className={s.note}>No website yet.</p>
          )}

          <h3 className={s.h3}>What they have made</h3>
          <div className={s.tiles}>
            <Tile label="Invoices saved" value={info.counts.invoices} />
            <Tile label="QR codes saved" value={info.counts.savedQr} />
            <Tile
              label="Tracked QR codes"
              value={info.counts.trackedQr}
              note={`of ${info.tracking.limit === null ? "unlimited" : info.tracking.limit} on ${info.user.planName}`}
            />
            <Tile
              label="Scans on those"
              value={info.counts.trackedScans}
              note={info.counts.campaigns ? `${info.counts.campaigns} campaign${info.counts.campaigns === 1 ? "" : "s"}` : "no campaigns"}
            />
            <Tile
              label="Leads"
              value={info.counts.leads}
              note={info.latestLead ? `latest ${day(info.latestLead)}` : "none yet"}
            />
          </div>
          <p className={s.note}>
            Leads are counted here, not shown: they are other people&apos;s contact details.
          </p>
            </>
          ) : null}
        </>
      ) : null}
    </div>
  )
}

const UsersAdmin = () => {
  const [data, setData] = React.useState(null)
  const [error, setError] = React.useState("")
  const [signedOut, setSignedOut] = React.useState(false)
  const [denied, setDenied] = React.useState(false)
  const [query, setQuery] = React.useState("")
  const [filter, setFilter] = React.useState("all")
  const [sort, setSort] = React.useState("login")
  const [selected, setSelected] = React.useState("")

  // A person can be linked to: /admin/users/#<id>.
  React.useEffect(() => {
    const read = () => setSelected((window.location.hash || "").replace("#", ""))
    read()
    window.addEventListener("hashchange", read)
    return () => window.removeEventListener("hashchange", read)
  }, [])

  const open = id => {
    window.location.hash = id
  }
  const back = () => {
    window.history.pushState("", document.title, window.location.pathname + window.location.search)
    setSelected("")
  }

  React.useEffect(() => {
    let alive = true
    call({ action: "list" }).then(res => {
      if (!alive) return
      if (res.status === 401) return setSignedOut(true)
      if (res.status === 403) return setDenied(true)
      if (!res.ok) return setError(res.body.message || `Could not load the users (HTTP ${res.status}).`)
      setData(res.body)
    })
    return () => {
      alive = false
    }
  }, [])

  const rows = React.useMemo(() => {
    if (!data) return []
    const q = query.trim().toLowerCase()
    const keep = data.users.filter(u => {
      if (filter === "affiliate" && !u.isAffiliate) return false
      if (filter === "admin" && !u.isAdmin) return false
      if (["free", "premium", "leads"].includes(filter) && u.plan !== filter) return false
      return !q || u.email.toLowerCase().includes(q) || (u.name || "").toLowerCase().includes(q)
    })
    const by = {
      login: (a, b) => (b.lastLogin || "").localeCompare(a.lastLogin || ""),
      joined: (a, b) => b.createdAt.localeCompare(a.createdAt),
      email: (a, b) => a.email.localeCompare(b.email),
    }
    return [...keep].sort(by[sort])
  }, [data, query, filter, sort])

  if (signedOut) return <p className={s.note}>Log in with an administrator account to see the users.</p>
  if (denied) return <p className={s.note}>This account is not an administrator, so the users are not shown here.</p>
  if (error) return <p className={s.error}>{error}</p>
  if (!data) return <p className={s.note}>Loading the users…</p>

  if (selected) return <Detail id={selected} onBack={back} />

  const t = data.totals
  return (
    <div>
      <p className={s.summary}>
        <strong>{t.people}</strong> people · {t.free} free · {t.premium} premium · {t.leads} lead
        generation · {t.affiliates} affiliate{t.affiliates === 1 ? "" : "s"} · {t.admins} admin
        {t.admins === 1 ? "" : "s"}
        {t.anonymous ? ` · ${t.anonymous} anonymous checkout session${t.anonymous === 1 ? "" : "s"} not listed` : ""}
      </p>

      <div className={s.controls}>
        <input
          className={s.input}
          type="search"
          placeholder="Search by email or name"
          value={query}
          onChange={e => setQuery(e.target.value)}
          aria-label="Search users"
        />
        <select className={s.input} value={filter} onChange={e => setFilter(e.target.value)} aria-label="Type">
          {FILTERS.map(f => (
            <option key={f.id} value={f.id}>
              {f.label}
            </option>
          ))}
        </select>
        <select className={s.input} value={sort} onChange={e => setSort(e.target.value)} aria-label="Sort by">
          {SORTS.map(o => (
            <option key={o.id} value={o.id}>
              Sort: {o.label}
            </option>
          ))}
        </select>
      </div>

      <div className={s.tableWrap}>
        <table className={s.table}>
          <thead>
            <tr>
              <th scope="col">User</th>
              <th scope="col">Type</th>
              <th scope="col">Joined</th>
              <th scope="col">Last login</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(u => (
              <tr key={u.id}>
                <td>
                  <button type="button" className={s.person} onClick={() => open(u.id)}>
                    <span className={s.personName}>{u.name || u.email}</span>
                    {u.name ? <span className={s.personEmail}>{u.email}</span> : null}
                  </button>
                </td>
                <td>
                  <Badges user={u} />
                </td>
                <td>{day(u.createdAt)}</td>
                <td>{u.lastLogin ? when(u.lastLogin) : <span className={s.never}>Never</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {rows.length === 0 ? <p className={s.note}>Nobody matches that.</p> : null}
    </div>
  )
}

export default UsersAdmin
