import * as React from "react"
import { Link } from "gatsby"
import Header from "../../components/Header"
import Seo from "../../components/Seo"
import UsersAdmin from "../../components/admin/UsersAdmin"
import * as s from "../../components/admin/Admin.module.css"

/**
 * Users, on their own page — FCS-090.
 * ============================================================================
 * Its own page for the same reason /admin/limits is: looking at who is here
 * is a different errand from rescuing one locked-out customer. The list gates
 * itself — it asks the server, and an account without an admin row is told so
 * rather than shown an empty table.
 */
const UsersPage = () => (
  <>
    <Header />
    <main className={s.page} data-print="hide">
      <div className="container">
        <div className={s.head}>
          <h1 className={s.title}>Users</h1>
        </div>
        <p className={s.lead}>
          Everyone with an account: what they pay for, when they joined, when they last logged in.
          Click a name to see their website and what they have made.
        </p>

        <div className={s.card}>
          <UsersAdmin />
        </div>

        <p className={s.lead}>
          <Link to="/admin/">Back to Admin</Link>
        </p>
      </div>
    </main>
  </>
)

export const Head = () => <Seo title="Users" description="Internal tools." noindex />

export default UsersPage
