import * as React from "react"
import { apiUrl } from "../../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { supabase } from "../../lib/supabase"
import * as s from "./LogsAdmin.module.css"

/**
 * What people did, newest first — FCS-099.
 * ============================================================================
 * One line per action: which account, what they did, when, and whether it
 * worked. "jo@acme.com · searched for a domain · 20 Oct, 14:02 · Success".
 *
 * Read-only on purpose. A log an administrator can edit is not evidence of
 * anything, so there is no delete and no edit here — rows leave only through
 * the retention period in project.json.
 *
 * ── THE SAME LINES, FILTERED THREE WAYS ────────────────────────────────────
 * Failures only (the question support actually asks), a kind of action, and a
 * text search across the action and its detail. `?user=<id>` narrows it to one
 * account, which is how the users screen links here.
 *
 * ── WHERE IT STOPS ─────────────────────────────────────────────────────────
 * It shows what the log holds, which is a short line per action and nothing
 * the customer typed into a form. There is no way to see an enquiry's words
 * from here, because they are never written down here.
 */

const call = async body => {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const token = data?.session?.access_token

  const res = await fetch(apiUrl("admin-logs"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { ok: res.ok, status: res.status, body: await res.json().catch(() => ({})) }
}

/** What each action code means, in words. Unknown codes are shown as they are. */
const LABELS = {
  "domain.search": "Searched for a domain",
  "domain.connect": "Connected a domain",
  "domain.check": "Checked the nameservers",
  "domain.wire": "Pointed a domain at the website",
  "domain.purchase": "Bought a domain",
  "checkout.start": "Started a checkout",
  "payment.completed": "Payment completed",
  "payment.failed": "Payment failed",
  "subscription.updated": "Subscription changed",
  "subscription.ended": "Subscription ended",
  "site.publish": "Published a website",
  "document.save": "Saved a document",
  "document.update": "Edited a saved document",
  "document.rename": "Renamed a document",
  "document.delete": "Deleted a document",
  "qr.create": "Made a tracked QR code",
  "qr.update": "Changed a tracked QR code",
  "qr.delete": "Deleted a tracked QR code",
  "qr.campaign.create": "Made a QR campaign",
  "qr.campaign.delete": "Deleted a QR campaign",
  "lead.received": "Received an enquiry",
  "affiliate.link.save": "Saved an advert link",
  "webhook.error": "Stripe event could not be recorded",
  "admin.limits.set": "Admin: changed a plan limit",
  "admin.settings.set": "Admin: changed a setting",
  "admin.templates.sync": "Admin: synced the template library",
  "admin.templates.set": "Admin: changed a template",
  "admin.user.view": "Admin: opened an account",
  "admin.user.permissions": "Admin: changed a user's permissions",
  "admin.user.role": "Admin: changed a user's role",
  "admin.actions.run": "Admin: ran account actions",
}

export const labelFor = action => LABELS[action] || action

const KINDS = [
  { id: "", label: "Everything" },
  { id: "domain", label: "Domains" },
  { id: "checkout", label: "Checkout" },
  { id: "payment", label: "Payments" },
  { id: "subscription", label: "Subscriptions" },
  { id: "site", label: "Websites" },
  { id: "document", label: "Invoices & QR saves" },
  { id: "qr", label: "Tracked QR codes" },
  { id: "lead", label: "Enquiries" },
  { id: "affiliate", label: "Affiliates" },
  { id: "admin", label: "Admin actions" },
]

const when = value => {
  const d = new Date(value)
  if (Number.isNaN(d.getTime())) return ""
  return d.toLocaleString(undefined, {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  })
}

const who = (email, id) => email || (id ? `${id.slice(0, 8)}…` : "—")

const LogsAdmin = ({ user = "" }) => {
  const [rows, setRows] = React.useState([])
  const [next, setNext] = React.useState(null)
  const [keeps, setKeeps] = React.useState(null)
  const [state, setState] = React.useState("loading") // loading | ready | denied | error
  const [message, setMessage] = React.useState("")
  const [more, setMore] = React.useState(false)

  const [outcome, setOutcome] = React.useState("")
  const [kind, setKind] = React.useState("")
  const [text, setText] = React.useState("")
  const [query, setQuery] = React.useState("")
  const [tick, setTick] = React.useState(0)

  // The search box waits for a pause rather than asking on every keystroke.
  React.useEffect(() => {
    const id = setTimeout(() => setQuery(text.trim()), 350)
    return () => clearTimeout(id)
  }, [text])

  const filters = React.useMemo(
    () => ({ outcome, kind, q: query, ...(user ? { subject: user } : {}) }),
    [outcome, kind, query, user]
  )

  React.useEffect(() => {
    let alive = true
    setState(prev => (prev === "denied" ? prev : "loading"))
    call({ action: "list", limit: 50, ...filters }).then(res => {
      if (!alive) return
      if (res.status === 401) {
        setMessage("Log in with an administrator account to see the log.")
        return setState("denied")
      }
      if (res.status === 403) {
        setMessage("This account is not an administrator, so the log is not shown here.")
        return setState("denied")
      }
      if (!res.ok) {
        setMessage(res.body.message || `The log did not load (HTTP ${res.status}).`)
        return setState("error")
      }
      setRows(res.body.rows || [])
      setNext(res.body.next)
      setKeeps(res.body.keeps || null)
      setState("ready")
    })
    return () => {
      alive = false
    }
  }, [filters, tick])

  const older = async () => {
    setMore(true)
    const res = await call({ action: "list", limit: 50, before: next, ...filters })
    setMore(false)
    if (!res.ok) {
      setMessage(res.body.message || "Could not load older lines.")
      return setState("error")
    }
    setRows(prev => [...prev, ...(res.body.rows || [])])
    setNext(res.body.next)
  }

  if (state === "denied") return <p className={s.note}>{message}</p>

  return (
    <div>
      {user ? (
        <p className={s.scope}>
          Showing one account only. <a href="/admin/logs/">Show everyone</a>
        </p>
      ) : null}

      <div className={s.controls}>
        <input
          className={s.input}
          type="search"
          value={text}
          onChange={e => setText(e.target.value)}
          placeholder="Search the log: a domain, a plan, a reason"
          aria-label="Search the log"
        />
        <select
          className={s.input}
          value={kind}
          onChange={e => setKind(e.target.value)}
          aria-label="Kind of action"
        >
          {KINDS.map(k => (
            <option key={k.id} value={k.id}>
              {k.label}
            </option>
          ))}
        </select>
        <select
          className={s.input}
          value={outcome}
          onChange={e => setOutcome(e.target.value)}
          aria-label="Outcome"
        >
          <option value="">Success and failure</option>
          <option value="failed">Failures only</option>
          <option value="ok">Successes only</option>
        </select>
        <button type="button" className={s.refresh} onClick={() => setTick(t => t + 1)}>
          Refresh
        </button>
      </div>

      {state === "error" ? <p className={s.error}>{message}</p> : null}
      {state === "loading" && rows.length === 0 ? <p className={s.note}>Loading the log…</p> : null}

      {state === "ready" && rows.length === 0 ? (
        <p className={s.note}>Nothing in the log matches that.</p>
      ) : null}

      {rows.length > 0 ? (
        <ul className={s.list} aria-label="Action log">
          {rows.map(r => (
            <li key={r.id} className={s.line} data-id={r.id} data-ok={r.ok ? "true" : "false"}>
              <span className={s.when}>{when(r.at)}</span>
              <span className={s.account}>
                {r.subject ? (
                  <a href={`/admin/logs/?user=${r.subject}`} title="Only this account">
                    {who(r.subjectEmail, r.subject)}
                  </a>
                ) : (
                  "Visitor"
                )}
                {r.actor && r.actor !== r.subject ? (
                  <span className={s.by}> · by {who(r.actorEmail, r.actor)}</span>
                ) : null}
              </span>
              <span className={s.what}>
                <strong>{labelFor(r.action)}</strong>
                {r.detail ? <span className={s.detail}>{r.detail}</span> : null}
              </span>
              <span className={s.result} data-ok={r.ok ? "true" : "false"}>
                {r.ok ? "Success" : "Failed"}
              </span>
            </li>
          ))}
        </ul>
      ) : null}

      {next ? (
        <button type="button" className={s.older} onClick={older} disabled={more}>
          {more ? "Loading…" : "Show older"}
        </button>
      ) : null}

      {keeps ? (
        <p className={s.note}>
          The log keeps the last {keeps.days} days, and never more than{" "}
          {keeps.rows.toLocaleString()} lines. It records what was done and whether it worked,
          never what a customer typed into a form.
        </p>
      ) : null}
    </div>
  )
}

export default LogsAdmin
