import * as React from "react"
import { PLAN_CHOICES, clearSandbox, setSandbox, useSandbox, useTestMode } from "../../lib/test-mode"
import { adminCall } from "./admin-call"
import { labelFor } from "./LogsAdmin"
import TestModeToggle from "./TestModeToggle"
import * as s from "./Permissions.module.css"

/**
 * One customer's permissions — FCS-095, FCS-097.
 * ============================================================================
 * What an administrator may set by hand on somebody's account: which plan they
 * are on, and whether they have a domain (and which). The same two controls
 * work in two completely different ways depending on the TEST MODE switch at
 * the top, and the whole screen is built around never letting those blur:
 *
 *   TEST MODE ON    Apply writes the administrator's SANDBOX in their own
 *                   browser. The customer's account is not touched, nothing
 *                   is sent. "Open their account in test mode" then shows the
 *                   customer's account with those changes laid over it.
 *   TEST MODE OFF   Apply changes the REAL account. The button turns red,
 *                   says so, and asks a second time before it does it.
 *
 * ── NEVER A SILENT OVERWRITE ───────────────────────────────────────────────
 * A change to a real account needs two deliberate clicks, and what is about to
 * change is spelled out in the question. A plan given by hand can be written
 * back by a later Stripe event, so when the customer is billed through Stripe
 * the answer says so.
 */

const planLabel = id => PLAN_CHOICES.find(p => p.id === id)?.label || id

export const UserPermissions = ({ info, reload }) => {
  const id = info.user.id
  const testMode = useTestMode()
  const sandbox = useSandbox(id)

  const realPlan = info.user.plan
  const realDomain = info.domain // null | { domain, status, source, setByAdmin }

  const [plan, setPlan] = React.useState(realPlan)
  const [has, setHas] = React.useState(Boolean(realDomain))
  const [domain, setDomain] = React.useState(realDomain?.domain || "")
  const [confirm, setConfirm] = React.useState("") // "" | "plan" | "domain"
  const [busy, setBusy] = React.useState(false)
  const [message, setMessage] = React.useState({ kind: "", text: "" })

  // The drafts show what is in force for the current mode, and follow it.
  React.useEffect(() => {
    if (testMode === null) return
    setPlan(testMode ? sandbox.plan || realPlan : realPlan)
    setHas(testMode && sandbox.domain !== undefined ? sandbox.domain !== null : Boolean(realDomain))
    setDomain(
      (testMode && typeof sandbox.domain === "string" ? sandbox.domain : realDomain?.domain) || ""
    )
    setConfirm("")
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [testMode, sandbox.plan, sandbox.domain, realPlan, realDomain?.domain])

  if (testMode === null) return null

  const say = (kind, text) => setMessage({ kind, text })

  // ── plan ──
  const applyPlan = async () => {
    say("", "")
    if (testMode) {
      setSandbox(id, { plan: plan === realPlan ? undefined : plan })
      return say("ok", plan === realPlan ? "Sandbox plan cleared: they appear on their real plan." : `Sandbox: they now appear on ${planLabel(plan)}. Their real plan is unchanged.`)
    }
    if (plan === realPlan) return say("warn", `They are already on ${planLabel(plan)}.`)
    if (confirm !== "plan") return setConfirm("plan")
    setBusy(true)
    const res = await adminCall("admin-users", { action: "set-plan", id, plan })
    setBusy(false)
    setConfirm("")
    if (!res.ok) return say("error", res.body.message || "That did not save.")
    say("ok", `Saved. ${info.user.email} is now on ${planLabel(plan)}.${res.body.stripeNote ? ` ${res.body.stripeNote}` : ""}`)
    reload()
  }

  // ── domain ──
  const applyDomain = async () => {
    say("", "")
    const typed = domain.trim().toLowerCase()
    if (has && !typed) return say("error", "Type the domain they have.")
    if (testMode) {
      const same = has ? realDomain?.domain === typed : !realDomain
      setSandbox(id, { domain: same ? undefined : has ? typed : null })
      return say(
        "ok",
        same
          ? "Sandbox domain cleared: they appear as they really are."
          : has
            ? `Sandbox: they now appear to have ${typed}. Their real account is unchanged.`
            : "Sandbox: they now appear to have no domain. Their real account is unchanged."
      )
    }
    if (confirm !== "domain") return setConfirm("domain")
    setBusy(true)
    const res = await adminCall("admin-users", { action: "set-domain", id, has, domain: typed })
    setBusy(false)
    setConfirm("")
    if (!res.ok) return say("error", res.body.message || "That did not save.")
    say("ok", has ? `Saved. ${info.user.email} now has ${res.body.domain?.domain || typed}.` : `Saved. ${info.user.email} no longer has a domain.`)
    reload()
  }

  const hasSandbox = sandbox.plan !== undefined || sandbox.domain !== undefined
  const sandboxDomain = sandbox.domain === null ? "no domain" : sandbox.domain

  return (
    <div data-testid="permissions">
      <TestModeToggle />

      <section className={s.section}>
        <h3 className={s.sectionTitle}>Plan</h3>
        <p className={s.help}>
          What they are on decides what their account allows: saved invoices, tracked QR codes,
          enquiries.
        </p>
        <p className={s.facts}>
          Real plan: <strong>{planLabel(realPlan)}</strong>
          {sandbox.plan ? (
            <span className={s.pill}>Sandbox: {planLabel(sandbox.plan)}</span>
          ) : null}
        </p>
        <div className={s.row}>
          <select
            className={s.input}
            value={plan}
            onChange={e => {
              setPlan(e.target.value)
              setConfirm("")
            }}
            aria-label="Plan"
          >
            {PLAN_CHOICES.map(p => (
              <option key={p.id} value={p.id}>
                {p.label}
              </option>
            ))}
          </select>
          <button
            type="button"
            className={s.apply}
            data-live={!testMode ? "true" : undefined}
            onClick={applyPlan}
            disabled={busy}
          >
            {testMode
              ? "Apply to sandbox"
              : confirm === "plan"
                ? `Yes, change ${info.user.email}’s real plan`
                : "Apply to the real account"}
          </button>
          {confirm === "plan" ? (
            <button type="button" className={s.ghost} onClick={() => setConfirm("")}>
              Cancel
            </button>
          ) : null}
        </div>
      </section>

      <section className={s.section}>
        <h3 className={s.sectionTitle}>Domain</h3>
        <p className={s.help}>
          Whether they have a domain of their own. It decides whether the free-domain credit is
          offered and what the domain page shows them.
        </p>
        <p className={s.facts}>
          Real:{" "}
          <strong>
            {realDomain
              ? `${realDomain.domain} (${realDomain.status}${realDomain.setByAdmin ? ", set by an administrator" : realDomain.source === "bought" ? ", bought through us" : ", connected"})`
              : "no domain"}
          </strong>
          {sandbox.domain !== undefined ? <span className={s.pill}>Sandbox: {sandboxDomain}</span> : null}
        </p>
        <div className={s.row}>
          <label className={s.check}>
            <input
              type="checkbox"
              checked={has}
              onChange={e => {
                setHas(e.target.checked)
                setConfirm("")
              }}
              aria-label="Has a domain"
            />
            Has a domain
          </label>
          <input
            className={`${s.input} ${s.grow}`}
            value={domain}
            onChange={e => {
              setDomain(e.target.value)
              setConfirm("")
            }}
            placeholder="yourbusiness.com"
            aria-label="Domain"
            disabled={!has}
            autoComplete="off"
            spellCheck="false"
          />
          <button
            type="button"
            className={s.apply}
            data-live={!testMode ? "true" : undefined}
            onClick={applyDomain}
            disabled={busy}
          >
            {testMode
              ? "Apply to sandbox"
              : confirm === "domain"
                ? has
                  ? `Yes, give ${info.user.email} this domain`
                  : `Yes, remove ${info.user.email}’s domain`
                : "Apply to the real account"}
          </button>
          {confirm === "domain" ? (
            <button type="button" className={s.ghost} onClick={() => setConfirm("")}>
              Cancel
            </button>
          ) : null}
        </div>
        {!testMode && realDomain && !realDomain.setByAdmin ? (
          <p className={s.note}>
            This is a real domain with a Cloudflare zone behind it. Removing it here marks it
            failed so the account stops counting it — the zone and its record are kept, and
            putting the same name back reactivates it.
          </p>
        ) : null}
      </section>

      {message.text ? (
        <p className={message.kind === "error" ? s.error : message.kind === "warn" ? s.warn : s.ok} role="status">
          {message.text}
        </p>
      ) : null}

      <section className={s.section}>
        <h3 className={s.sectionTitle}>See it as they do</h3>
        <p className={s.help}>
          Opens their account area in a new tab, with your sandbox laid over it. You can look
          around and change the sandbox plan and domain from the bar at the top; nothing you do
          there changes their account, and everything that would write is refused.
        </p>
        <div className={s.row}>
          <a
            className={s.open}
            href={`/account/?viewAs=${id}`}
            target="_blank"
            rel="noreferrer"
            aria-disabled={!testMode ? "true" : undefined}
            tabIndex={testMode ? undefined : -1}
          >
            Open their account in test mode
          </a>
          {hasSandbox ? (
            <button type="button" className={s.ghost} onClick={() => clearSandbox(id)}>
              Reset sandbox
            </button>
          ) : null}
        </div>
        {!testMode ? <p className={s.note}>Turn test mode on to view an account this way.</p> : null}
        <p className={s.note}>
          Their enquiries and recovery code are never shown, in test mode or anywhere else in admin.
        </p>
      </section>
    </div>
  )
}

const when = value => {
  const d = new Date(value)
  return Number.isNaN(d.getTime())
    ? ""
    : d.toLocaleString(undefined, { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })
}

/** The last few things they did, with the way through to all of it. */
export const UserActivity = ({ id }) => {
  const [rows, setRows] = React.useState(null)
  const [error, setError] = React.useState("")

  React.useEffect(() => {
    let alive = true
    adminCall("admin-logs", { action: "list", subject: id, limit: 15 }).then(res => {
      if (!alive) return
      if (!res.ok) return setError(res.body.message || "The activity did not load.")
      setRows(res.body.rows || [])
    })
    return () => {
      alive = false
    }
  }, [id])

  if (error) return <p className={s.error}>{error}</p>
  if (!rows) return <p className={s.note}>Loading their activity…</p>

  return (
    <div data-testid="activity">
      {rows.length === 0 ? <p className={s.note}>Nothing recorded for this account yet.</p> : null}
      {rows.length > 0 ? (
        <ul className={s.lines} aria-label="Recent activity">
          {rows.map(r => (
            <li key={r.id} className={s.line} data-ok={r.ok ? "true" : "false"}>
              <span className={s.when}>{when(r.at)}</span>
              <span className={s.what}>
                <strong>{labelFor(r.action)}</strong>
                {r.detail ? <span className={s.detail}>{r.detail}</span> : null}
              </span>
              <span className={s.result} data-ok={r.ok ? "true" : "false"}>
                {r.ok ? "Success" : "Failed"}
              </span>
            </li>
          ))}
        </ul>
      ) : null}
      <p className={s.note}>
        <a href={`/admin/logs/?user=${id}`}>See everything for this account →</a>
      </p>
    </div>
  )
}

export default UserPermissions
