import * as React from "react"
import { setTestMode, useTestMode } from "../../lib/test-mode"
import * as s from "./Permissions.module.css"

/**
 * The test-mode switch — FCS-095, FCS-097.
 * ============================================================================
 * One switch, shown at the top of every screen where an administrator can
 * change somebody's plan or domain, and shared between them: turning it off on
 * the users screen turns it off in Settings too, because "am I about to change
 * a real account" must have the same answer wherever you are asking.
 *
 * It is ON unless somebody has turned it off, and says in words what each
 * state does. A switch that is only a colour is how a real customer's plan
 * gets changed by somebody who thought they were experimenting.
 */
const TestModeToggle = () => {
  const on = useTestMode()
  if (on === null) return null

  return (
    <div className={s.mode} data-on={on ? "true" : "false"} data-testid="test-mode">
      <div className={s.modeText}>
        <strong>Test mode {on ? "is on" : "is OFF"}</strong>
        <span>
          {on
            ? "Changes here are a sandbox: only you see them, when you open their account in test mode. The customer’s real account is not touched."
            : "Changes here are saved to the customer’s REAL account, and they will see them."}
        </span>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={on}
        aria-label="Test mode"
        className={s.toggle}
        data-on={on ? "true" : undefined}
        onClick={() => setTestMode(!on)}
      >
        <span className={s.knob} />
      </button>
    </div>
  )
}

export default TestModeToggle
